  const r2Center = (posZ - TAKEOFF.z + TASK.startOffset) / (2 * TASK.startOffset);
  const tol = (1.5 * TASK.positionNoise) / (2 * TASK.startOffset) + 1e-9;
  const r1Lo = ((r1Center - tol) * 4294967296) >>> 0;
  const r1Hi = ((r1Center + tol) * 4294967296) >>> 0;
  const r2Lo = ((r2Center - tol) * 4294967296) >>> 0;
  const r2Hi = ((r2Center + tol) * 4294967296) >>> 0;

  let found = -1;
  for (let s = 0; s <= 2000000; s++) {
