  let rollRef = 0, pitchRef = 0, intRoll = 0, intPitch = 0;
  let crossCommit = false, lastGate = -1;

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const dt = 0.01;

      // Update lagged collective thrust estimate
      uT += (prevThrust - uT) * (1 - Math.exp(-dt / 0.04));

      // Exact thrust unit vector from current measured attitude
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const mEst = clamp(14.8 / kt, 0.60, 0.85);
      const dragCoeff = 0.42 / mEst;

      // Momentum-based Disturbance Observer (no velocity differentiation)
      const Ly = 14, Lxz = 22;
      if (!dobInit && p.y > 0.085) {
        dobInit = true;
        zy = Ly * v.y;
        zx = Lxz * v.x;
        zz = Lxz * v.z;
      }
      if (dobInit && p.y > 0.078) {
        const ayNom = kt * uT * dirY - dragCoeff * v.y - 9.81;
        dyEst = clamp(Ly * v.y - zy, -6.0, 6.0);
        zy += Ly * (ayNom + dyEst) * dt;

        // Slowly adapt kt so vertical thrust scale converges
        if (uT * dirY > 0.3) {
          const dKt = 0.4 * dyEst * dt / (uT * dirY);
          kt = clamp(kt + dKt, 13.5, 27.5);
        }

        const sumPerMass = Math.max(0, kt * uT + dyEst / Math.max(0.5, dirY));
        const axNom = sumPerMass * dirX - dragCoeff * v.x;
        const azNom = sumPerMass * dirZ - dragCoeff * v.z;

        dxEst = clamp(Lxz * v.x - zx, -8.5, 8.5);
        zx += Lxz * (axNom + dxEst) * dt;

        dzEst = clamp(Lxz * v.z - zz, -8.5, 8.5);
        zz += Lxz * (azNom + dzEst) * dt;
      }

      // Navigation & Trajectory Planning
      let tx, ty, tz, vxFf = 0, vyFf = 0, vzFf = 0;
      let maxTilt = 0.50;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (lastGate !== obs.gateIndex) {
          lastGate = obs.gateIndex;
          crossCommit = false;
          intX *= 0.3;
          intZ *= 0.3;
        }
        ty = gate.y;
        tz = gate.z;

        const dxGate = gate.x - p.x;
        const tPred = clamp(dxGate / Math.max(0.35, v.x), 0.05, 0.30);
        const zPred = Math.abs((p.z - gate.z) + v.z * tPred);
        const yPred = Math.abs((p.y - gate.y) + v.y * tPred);
        const zErr = Math.abs(p.z - gate.z);
        const yErr = Math.abs(p.y - gate.y);

        const alignedToStart = zErr < 0.060 && zPred < 0.070 && Math.abs(v.z) < 0.32 &&
                               yErr < 0.12 && yPred < 0.14 && Math.abs(v.y) < 0.45 &&
                               dxGate < 0.38;
        const safeToContinue = zErr < 0.085 && zPred < 0.092 && yErr < 0.16 && yPred < 0.18;

        if (alignedToStart) crossCommit = true;
        else if (!safeToContinue) crossCommit = false;

        if (crossCommit) {
          tx = gate.x + 0.32;
          vxFf = 0.55;
        } else {
          tx = gate.x - 0.24;
          // If approaching from far away, limit approach speed smoothly
          if (dxGate > 0.35) {
            vxFf = clamp(0.6 * (dxGate - 0.24), 0, 0.65);
          }
        }
      } else {
        // Landing phase
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distH = Math.hypot(tx - p.x, tz - p.z);
        const speedH = Math.hypot(v.x, v.z);

        if (distH > 0.35) {
          // Glide down smoothly toward pad
          ty = clamp(0.22 + 0.75 * (distH - 0.15), 0.22, 1.05);
        } else if (distH > 0.095 || speedH > 0.28) {
          ty = 0.16;
          maxTilt = 0.35;
        } else {
          // Final descent & hold on pad
          ty = 0.04;
          maxTilt = 0.14;
          vyFf = p.y > 0.11 ? -0.22 : -0.08;
        }

        // Once touching or nearly touching the pad inside radius, cut thrust to settle cleanly
        if (distH < 0.115 && p.y <= 0.088 && speedH < 0.35 && Math.abs(v.y) < 0.35) {
          const axPad = clamp(3.0 * (tx - p.x) - 2.5 * v.x - 0.5 * dxEst, -1.2, 1.2);
          const azPad = clamp(3.0 * (tz - p.z) - 2.5 * v.z - 0.5 * dzEst, -1.2, 1.2);
          const pitchPad = clamp((cy * axPad - sy * azPad) / 9.81, -0.11, 0.11);
          const rollPad = clamp(-(sy * axPad + cy * azPad) / 9.81, -0.11, 0.11);
          prevThrust = 0.02;
          return { thrust: 0.02, roll: rollPad, pitch: pitchPad, yawRate: clamp(-3 * att.yaw, -2, 2) };
        }
      }

      // Position error & small integral for zero steady-state offset
      const ex = tx - p.x, ey = ty - p.y, ez = tz - p.z;
      if (Math.abs(ex) < 0.25) intX = clamp(intX + ex * dt, -0.35, 0.35);
      if (Math.abs(ez) < 0.25) intZ = clamp(intZ + ez * dt, -0.35, 0.35);

      const exClamped = clamp(ex, -0.65, 0.65);
      const ezClamped = clamp(ez, -0.65, 0.65);
      const eyClamped = clamp(ey, -0.65, 0.65);

      const axDes = clamp(6.2 * exClamped + 4.0 * (vxFf - v.x) + 1.2 * intX, -4.5, 4.5);
      const azDes = clamp(6.8 * ezClamped + 4.3 * (vzFf - v.z) + 1.4 * intZ, -4.5, 4.5);
      const ayDes = clamp(6.8 * eyClamped + 4.2 * (vyFf - v.y), -4.0, 5.0);

      // Required thrust acceleration vector (cancelling linear drag and wind/mass disturbance)
      const axT = axDes + dragCoeff * v.x - dxEst;
      const azT = azDes + dragCoeff * v.z - dzEst;
      const ayT = clamp(9.81 + ayDes + dragCoeff * v.y - dyEst, 2.5, 16.0);

      // Exact geometric attitude inversion
      const accBodyX = cy * axT - sy * azT;
      const accBodyZ = sy * axT + cy * azT;
      const pitchDes = clamp(Math.atan2(accBodyX, ayT), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(accBodyZ, Math.hypot(accBodyX, ayT)), -maxTilt, maxTilt);

      // Model-reference outer integral for weak-motor attitude offset compensation
      rollRef += (rollDes - rollRef) * (dt / 0.055);
      pitchRef += (pitchDes - pitchRef) * (dt / 0.055);
      if (p.y > 0.09) {
        intRoll = clamp(intRoll + (rollRef - att.roll) * dt * 2.2, -0.18, 0.18);
        intPitch = clamp(intPitch + (pitchRef - att.pitch) * dt * 2.2, -0.18, 0.18);
        intYaw = clamp(intYaw + att.yaw * dt * 1.5, -0.5, 0.5);
      }

      const rollCmd = clamp(rollDes + intRoll + 0.18 * (rollDes - att.roll) - 0.025 * rates.roll, -maxTilt, maxTilt);
      const pitchCmd = clamp(pitchDes + intPitch + 0.18 * (pitchDes - att.pitch) - 0.025 * rates.pitch, -maxTilt, maxTilt);
      const yawRateCmd = clamp(-3.5 * att.yaw - 2.0 * intYaw, -2, 2);

      const thrustCmd = clamp(ayT / (kt * Math.max(0.55, dirY)), 0, 1);
      prevThrust = thrustCmd;

      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
    },
  };
}

