export default function makeController() {
  let prevThrust = 0.45, uT = 0.45;
  let kt = 20.5;
  let zy = 0, zx = 0, zz = 0;
  let dyEst = 0, dxEst = 0, dzEst = 0;
  let dobYInit = false, dobXZInit = false;
  let intX = 0, intZ = 0, intYaw = 0;
  let rollRef = 0, pitchRef = 0, intRoll = 0, intPitch = 0;
  let crossCommit = false, lastGate = -1;

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  function desiredVel(err, vMax, kp, aBrake) {
    const a = Math.abs(err);
    if (a < 1e-6) return 0;
    const vLin = kp * a;
    const vSqrt = Math.sqrt(2 * aBrake * a);
    const s = Math.min(vMax, vLin, vSqrt);
    return err > 0 ? s : -s;
  }

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const dt = 0.01;

      // Update lagged collective thrust estimate
      uT += (prevThrust - uT) * (1 - Math.exp(-dt / 0.04));

      // Exact thrust unit vector from current measured attitude
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const mEst = clamp(14.8 / kt, 0.60, 0.85);
      const dragCoeff = 0.42 / mEst;

      // Momentum-based Disturbance Observer (only when clear of floor)
      const Ly = 12, Lxz = 24;
      if (p.y > 0.16) {
        if (!dobYInit) {
          dobYInit = true;
          zy = Ly * v.y - dyEst;
        }
        const ayNom = kt * uT * dirY - dragCoeff * v.y - 9.81;
        dyEst = clamp(Ly * v.y - zy, -5.5, 5.5);
        zy += Ly * (ayNom + dyEst) * dt;

        if (uT * dirY > 0.32) {
          const dKt = 0.5 * dyEst * dt / (uT * dirY);
          kt = clamp(kt + dKt, 13.5, 27.5);
        }
      } else {
        zy = Ly * v.y - dyEst;
      }

      if (p.y > 0.095) {
        if (!dobXZInit) {
          dobXZInit = true;
          zx = Lxz * v.x - dxEst;
          zz = Lxz * v.z - dzEst;
        }
        const sumPerMass = Math.max(0, kt * uT + dyEst / Math.max(0.5, dirY));
        const axNom = sumPerMass * dirX - dragCoeff * v.x;
        const azNom = sumPerMass * dirZ - dragCoeff * v.z;

        dxEst = clamp(Lxz * v.x - zx, -8.5, 8.5);
        zx += Lxz * (axNom + dxEst) * dt;

        dzEst = clamp(Lxz * v.z - zz, -8.5, 8.5);
        zz += Lxz * (azNom + dzEst) * dt;
      } else {
        zx = Lxz * v.x - dxEst;
        zz = Lxz * v.z - dzEst;
      }

      // Navigation & Trajectory Planning
      let tx, ty, tz;
      let vMaxX = 1.05, vMaxY = 1.05, vMaxZ = 1.05;
      let kpX = 2.4, kpY = 2.6, kpZ = 2.6;
      let kvX = 4.8, kvY = 5.0, kvZ = 5.2;
      let maxTilt = 0.48;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (lastGate !== obs.gateIndex) {
          lastGate = obs.gateIndex;
          crossCommit = false;
          intX = 0;
          intZ = 0;
        }
        ty = gate.y;
        tz = gate.z;

        const dxGate = gate.x - p.x;
        const zErr = Math.abs(p.z - gate.z);
        const yErr = Math.abs(p.y - gate.y);
        const tPred = clamp(dxGate / Math.max(0.40, v.x), 0.06, 0.32);
        const zPred = Math.abs((p.z - gate.z) + v.z * tPred);
        const yPred = Math.abs((p.y - gate.y) + v.y * tPred);

        const alignedToStart = dxGate > 0 && dxGate < 0.44 &&
                               zErr < 0.052 && zPred < 0.062 && Math.abs(v.z) < 0.22 &&
                               yErr < 0.105 && yPred < 0.125 && Math.abs(v.y) < 0.32;
        const safeToContinue = zErr < 0.078 && zPred < 0.088 && yErr < 0.155 && yPred < 0.175;

        if (alignedToStart) crossCommit = true;
        else if (!safeToContinue && dxGate > 0.06) crossCommit = false;

        if (crossCommit) {
          tx = gate.x + 0.35;
          vMaxX = 0.95;
          kpZ = 3.1;
          kvZ = 5.8;
          kpY = 3.0;
          kvY = 5.4;
        } else {
          // Hold safely in front of the gate plane until y and z are aligned
          const stageOffset = (yErr > 0.22 || zErr > 0.14) ? 0.42 : 0.34;
          tx = gate.x - stageOffset;
          vMaxX = (yErr > 0.30) ? 0.65 : 0.90;
        }
      } else {
        // Landing phase
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distH = Math.hypot(tx - p.x, tz - p.z);
        const speedH = Math.hypot(v.x, v.z);

        if (p.y <= 0.092 && distH > 0.125) {
          // Touched floor outside pad: hop up clear of floor friction first
          ty = 0.28;
          maxTilt = 0.35;
        } else if (distH > 0.30) {
          // Smooth glide slope toward pad
          ty = clamp(0.24 + 0.70 * (distH - 0.15), 0.24, 1.05);
          vMaxX = 0.95;
          vMaxZ = 0.95;
        } else if (distH > 0.085 || speedH > 0.22) {
          // Hover and center precisely over pad before final touchdown
          ty = 0.18;
          maxTilt = 0.36;
          kpX = 2.8;
          kpZ = 2.8;
        } else {
          // Aligned and slow over pad: descend gently onto pad
          ty = 0.03;
          vMaxY = 0.28;
          maxTilt = 0.14;
        }

        // Once resting inside pad radius with low speed, cut thrust to lock landing hold
        if (distH < 0.12 && p.y <= 0.088 && speedH < 0.35 && Math.abs(v.y) < 0.35) {
          const axPad = clamp(3.0 * (tx - p.x) - 2.0 * v.x - 0.4 * dxEst, -1.0, 1.0);
          const azPad = clamp(3.0 * (tz - p.z) - 2.0 * v.z - 0.4 * dzEst, -1.0, 1.0);
          const pitchPad = clamp((cy * axPad - sy * azPad) / 9.81, -0.10, 0.10);
          const rollPad = clamp(-(sy * axPad + cy * azPad) / 9.81, -0.10, 0.10);
          prevThrust = 0;
          return { thrust: 0, roll: rollPad, pitch: pitchPad, yawRate: clamp(-3 * att.yaw, -2, 2) };
        }
      }

      const ex = tx - p.x, ey = ty - p.y, ez = tz - p.z;
      if (Math.abs(ex) < 0.20 && p.y > 0.095) intX = clamp(intX + ex * dt, -0.35, 0.35);
      if (Math.abs(ez) < 0.20 && p.y > 0.095) intZ = clamp(intZ + ez * dt, -0.35, 0.35);

      const vxDes = desiredVel(ex, vMaxX, kpX, 2.0);
      const vyDes = desiredVel(ey, vMaxY, kpY, 2.2);
      const vzDes = desiredVel(ez, vMaxZ, kpZ, 2.0);

      const axDes = clamp(kvX * (vxDes - v.x) + 1.4 * intX, -4.5, 4.5);
      const azDes = clamp(kvZ * (vzDes - v.z) + 1.6 * intZ, -4.5, 4.5);
      const ayDes = clamp(kvY * (vyDes - v.y), -4.0, 5.0);

      // Required thrust acceleration vector (cancelling linear drag and wind/mass disturbance)
      const axT = axDes + dragCoeff * v.x - dxEst;
      const azT = azDes + dragCoeff * v.z - dzEst;
      const ayT = clamp(9.81 + ayDes + dragCoeff * v.y - dyEst, 2.5, 16.0);

      // Exact geometric attitude inversion
      const accBodyX = cy * axT - sy * azT;
      const accBodyZ = sy * axT + cy * azT;
      const pitchDes = clamp(Math.atan2(accBodyX, ayT), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(accBodyZ, Math.hypot(accBodyX, ayT)), -maxTilt, maxTilt);

      // Model-reference outer integral for weak-motor attitude offset compensation
      rollRef += (rollDes - rollRef) * (dt / 0.055);
      pitchRef += (pitchDes - pitchRef) * (dt / 0.055);
      if (p.y > 0.095) {
        intRoll = clamp(intRoll + (rollRef - att.roll) * dt * 2.2, -0.18, 0.18);
